// Cloudflare entry: the Next.js app (built by OpenNext) plus a timer that plays due matches.
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

type Env = { WORKER_SELF_REFERENCE: { fetch: (r: Request) => Promise<Response> }; CRON_SECRET?: string };

export default {
  fetch: handler.fetch,
  // Each call to /api/cron is its own request with its own CPU budget and plays one match.
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil: (p: Promise<unknown>) => void }) {
    ctx.waitUntil((async () => {
      for (let i = 0; i < 40; i++) {
        const res = await env.WORKER_SELF_REFERENCE.fetch(new Request(`https://kora.internal/api/cron?key=${encodeURIComponent(env.CRON_SECRET || '')}`));
        if (!res.ok) break;
        const j = (await res.json()) as { played: number; remaining: number };
        if (!j.remaining || !j.played) break;
      }
    })());
  },
};

// @ts-ignore re-exported for OpenNext features that use Durable Objects
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
